import { useEffect, useState } from 'react';
import { ActivityIndicator, FlatList, Text, View } from 'react-native';
import type { Item } from '../../domain/entities/item';
import { listItems } from '../../domain/usecases/listItems';

export function HomeScreen() {
  const [items, setItems] = useState<Item[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    listItems()
      .then(setItems)
      .catch(() => setError('Liste yüklenemedi'));
  }, []);

  if (error) return <Text>{error}</Text>;
  if (!items) return <ActivityIndicator />;
  if (items.length === 0) return <Text>Sipariş yok</Text>;

  return (
    <View>
      <Text>Siparişler</Text>
      <FlatList
        data={items}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => <Text>{item.title}</Text>}
      />
    </View>
  );
}

import { useState } from 'react';
import { Button, Text, TextInput, View } from 'react-native';

export function LoginScreen({ onSubmit }: { onSubmit: (email: string, password: string) => void }) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState<string | null>(null);

  return (
    <View>
      <Text>Giriş</Text>
      <TextInput
        autoCapitalize="none"
        keyboardType="email-address"
        placeholder="E-posta"
        value={email}
        onChangeText={setEmail}
      />
      <TextInput
        secureTextEntry
        placeholder="Şifre"
        value={password}
        onChangeText={setPassword}
      />
      {error ? <Text>{error}</Text> : null}
      <Button
        title="Giriş yap"
        onPress={() => {
          if (!email || !password) {
            setError('E-posta ve şifre gerekli');
            return;
          }
          setError(null);
          onSubmit(email, password);
        }}
      />
    </View>
  );
}

package httpapi

import (
	"encoding/json"
	"net/http"
)

type Item struct {
	ID       string `json:"id"`
	Title    string `json:"title"`
	Quantity int    `json:"quantity"`
}

func ItemsHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "method", http.StatusMethodNotAllowed)
		return
	}
	_ = json.NewEncoder(w).Encode([]Item{{
		ID: "1", Title: "Filtre kahve", Quantity: 1,
	}})
}

final class HomeItem {
  const HomeItem({required this.id, required this.title, required this.minutes});
  final String id;
  final String title;
  final int minutes;
}

import '../domain/entities/home_item.dart';
import 'package:http/http.dart' as http;
import 'dart:convert';

class HomeRepository {
  HomeRepository({http.Client? client}) : _client = client ?? http.Client();
  final http.Client _client;
  static const _base = 'http://127.0.0.1:47001';

  Future<List<HomeItem>> list() async {
    final res = await _client.get(Uri.parse('$_base/workouts'));
    if (res.statusCode != 200) {
      throw StateError('workouts_failed');
    }
    final raw = jsonDecode(res.body) as List<dynamic>;
    return raw
        .map((e) => HomeItem(
              id: e['id'] as String,
              title: e['title'] as String,
              minutes: e['minutes'] as int,
            ))
        .toList();
  }
}

import 'package:flutter/material.dart';
import '../../domain/entities/home_item.dart';
import '../../data/repositories/home_repository.dart';

class HomePage extends StatefulWidget {
  const HomePage({super.key});
  @override
  State<HomePage> createState() => _HomePageState();
}

class _HomePageState extends State<HomePage> {
  final _repo = HomeRepository();
  late Future<List<HomeItem>> _future;

  @override
  void initState() {
    super.initState();
    _future = _repo.list();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Antrenmanlar')),
      body: FutureBuilder<List<HomeItem>>(
        future: _future,
        builder: (context, snap) {
          if (snap.hasError) return const Center(child: Text('Yüklenemedi'));
          if (!snap.hasData) return const Center(child: CircularProgressIndicator());
          final items = snap.data!;
          if (items.isEmpty) return const Center(child: Text('Kayıt yok'));
          return ListView(
            children: [
              for (final item in items)
                ListTile(title: Text(item.title), subtitle: Text('${item.minutes} dk')),
            ],
          );
        },
      ),
    );
  }
}

import Foundation

struct Note: Identifiable, Equatable {
  let id: String
  var title: String
  var body: String
}

import SwiftUI

struct HomeView: View {
  let notes: [Note]
  let errorMessage: String?

  var body: some View {
    Group {
      if let errorMessage {
        Text(errorMessage)
      } else if notes.isEmpty {
        Text("Not yok")
      } else {
        List(notes) { note in
          Text(note.title)
        }
      }
    }
    .navigationTitle("Notlar")
  }
}

import SwiftUI

struct LoginView: View {
  @State private var email = ""
  @State private var password = ""
  @State private var error: String?
  var onSubmit: (String, String) -> Void

  var body: some View {
    Form {
      TextField("E-posta", text: $email)
        .textInputAutocapitalization(.never)
        .keyboardType(.emailAddress)
      SecureField("Şifre", text: $password)
      if let error { Text(error).foregroundStyle(.red) }
      Button("Giriş") {
        guard !email.isEmpty, !password.isEmpty else {
          error = "E-posta ve şifre gerekli"
          return
        }
        error = nil
        onSubmit(email, password)
      }
    }
    .navigationTitle("Giriş")
  }
}

